CREATE PROCEDURE GetCourseStudents
    @CourseId INT
AS
BEGIN
    SET NOCOUNT ON;
    SELECT s.Name, e.Grade
    FROM Enrollments e
    JOIN Students s ON s.Id = e.StudentId
    WHERE e.CourseId = @CourseId
    ORDER BY s.Name;
END;
GO

